script_win:
$app = "{{app}}"
$ws = New-Object -ComObject WScript.Shell
if ($app -eq 'Google Chrome') {
  $chrome = @((Join-Path $env:ProgramFiles 'Google/Chrome/Application/chrome.exe'), (Join-Path ${env:ProgramFiles(x86)} 'Google/Chrome/Application/chrome.exe'), (Join-Path $env:LOCALAPPDATA 'Google/Chrome/Application/chrome.exe')) | Where-Object { Test-Path $_ } | Select-Object -First 1
  if (-not $chrome) { $chrome = (Get-Command chrome.exe -ErrorAction SilentlyContinue).Source }
  if (-not $chrome) { throw 'Google Chrome is not installed.' }
  $launchArgs = @('"--profile-directory={{chrome_profile}}"')
  if ("{{chrome_home}}") { $launchArgs += '"{{chrome_home}}"' }
  Start-Process -FilePath $chrome -ArgumentList $launchArgs
} elseif ($app -eq 'Notepad') {
  Start-Process notepad.exe
} elseif ($app -eq 'Microsoft Edge') {
  Start-Process msedge.exe
} else {
  $menus = @((Join-Path $env:ProgramData 'Microsoft/Windows/Start Menu/Programs'), (Join-Path $env:AppData 'Microsoft/Windows/Start Menu/Programs'))
  $lnk = Get-ChildItem $menus -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | Where-Object { $_.BaseName -eq $app } | Select-Object -First 1
  if ($lnk) { Start-Process -FilePath $lnk.FullName }
  else {
    $exe = Get-Command $app -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $exe) { throw "$app is not installed." }
    Start-Process -FilePath $exe.Source
  }
}
Start-Sleep -Milliseconds 400
$null = $ws.AppActivate($app)
"$app opened"

$chrome = @((Join-Path $env:ProgramFiles 'Google/Chrome/Application/chrome.exe'), (Join-Path ${env:ProgramFiles(x86)} 'Google/Chrome/Application/chrome.exe'), (Join-Path $env:LOCALAPPDATA 'Google/Chrome/Application/chrome.exe')) | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $chrome) { $chrome = (Get-Command chrome.exe -ErrorAction SilentlyContinue).Source }
if (-not $chrome) { throw 'Chrome is not installed. Install Chrome to open websites.' }
$url = "{{browser_url}}"
Start-Process -FilePath $chrome -ArgumentList @('"--profile-directory={{chrome_profile}}"', $url)
$url
